 static void Compare(int angle){var left=Read(Out+"/MoeFace_Quality_"+angle+".png");var right=Read(Out+"/IndependentFemale_Face_"+angle+".png");var result=new Texture2D(left.width+right.width,left.height,TextureFormat.RGB24,false,true);result.SetPixels(0,0,left.width,left.height,left.GetPixels());result.SetPixels(left.width,0,right.width,right.height,right.GetPixels());result.Apply();File.WriteAllBytes(Out+"/IndependentFemale_Moe_Comparison_"+angle+".png",result.EncodeToPNG());UnityEngine.Object.DestroyImmediate(left);UnityEngine.Object.DestroyImmediate(right);UnityEngine.Object.DestroyImmediate(result);}
 struct BP{public Vector3 p,n;public Vector2 uv;public BoneWeight w;}
 static List<BP> ClipBody(List<BP> polygon,Func<BP,float> distance){var clipped=new List<BP>();if(polygon.Count==0)return clipped;var a=polygon[polygon.Count-1];float da=distance(a);foreach(var b in polygon){float db=distance(b);if((da>=0)!=(db>=0)){float t=da/(da-db);clipped.Add(new BP{p=Vector3.Lerp(a.p,b.p,t),n=Unit(Vector3.Lerp(a.n,b.n,t)),uv=Vector2.Lerp(a.uv,b.uv,t),w=Mix(a.w,b.w,t)});}if(db>=0)clipped.Add(b);a=b;da=db;}return clipped;}
 static void BodyFan(List<BP> polygon,List<BP> output){for(int i=1;i+1<polygon.Count;i++)output.AddRange(new[]{polygon[0],polygon[i],polygon[i+1]});}
 static BoneWeight Mix(BoneWeight a,BoneWeight b,float t){var values=new Dictionary<int,float>();Action<BoneWeight,float> add=(w,f)=>{int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] v={w.weight0,w.weight1,w.weight2,w.weight3};for(int k=0;k<4;k++){if(!values.ContainsKey(ids[k]))values[ids[k]]=0;values[ids[k]]+=v[k]*f;}};add(a,1-t);add(b,t);var top=values.OrderByDescending(v=>v.Value).Take(4).ToArray();var result=new BoneWeight();float sum=top.Sum(v=>v.Value);if(top.Length>0){result.boneIndex0=top[0].Key;result.weight0=top[0].Value/sum;}if(top.Length>1){result.boneIndex1=top[1].Key;result.weight1=top[1].Value/sum;}if(top.Length>2){result.boneIndex2=top[2].Key;result.weight2=top[2].Value/sum;}if(top.Length>3){result.boneIndex3=top[3].Key;result.weight3=top[3].Value/sum;}return result;}
 static void SliceBody(SkinnedMeshRenderer body,float height){
  var original=body.sharedMesh;var world=NurseAnatomyRender.WorldSkin(body);var positions=world.vertices;var normals=world.normals;var coords=original.uv;var weights=original.boneWeights;var input=original.GetTriangles(0);var output=new List<BP>();
  var raw=Read(Out+"/Atlas_Albedo.png");Func<Vector2,bool> blue=coord=>{var color=raw.GetPixelBilinear(coord.x,coord.y);return color.b>color.r*1.2f&&color.g>color.r*1.06f;};
  foreach(var offset in Enumerable.Range(0,input.Length/3).Select(i=>i*3)){
   var polygon=new List<BP>();for(int k=0;k<3;k++){int id=input[offset+k];polygon.Add(new BP{p=positions[id],n=normals[id],uv=coords[id],w=weights[id]});}
   bool cloth=polygon.Max(p=>p.p.y)<1.57f&&polygon.All(p=>blue(p.uv));
   if(cloth||polygon.Max(p=>p.p.y)<=height||polygon.Min(p=>p.p.x)>=.13f||polygon.Max(p=>p.p.x)<=-.13f){BodyFan(polygon,output);continue;}
   foreach(Func<BP,float> distance in new Func<BP,float>[]{p=>p.p.y-height,p=>.13f-p.p.x,p=>.13f+p.p.x}){if(polygon.Count<3)break;BodyFan(ClipBody(polygon,p=>-distance(p)),output);polygon=ClipBody(polygon,distance);}
