  var mesh=new Mesh{name="NurseBodyBelowIndependentHead",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,vertices=v,normals=n,uv=uv,boneWeights=bw,bindposes=original.bindposes,triangles=Enumerable.Range(0,v.Length).ToArray()};mesh.RecalculateTangents();mesh.RecalculateBounds();body.sharedMesh=mesh;File.WriteAllText(Out+"/independent-head-body-cut.txt","Clipped existing body triangles exactly at world y="+height+"m, interpolating UVs and normalized weights. Upper old head/hair geometry fully excluded, including triangles crossing the plane. Remaining body triangles="+output.Count/3+". Candidate only; source asset not overwritten.\n");UnityEngine.Object.DestroyImmediate(world);
 }
